//! The native convention's declaration (`TODO.md` §97, `docs/research/
//! declared-conventions.md`) is what this machine's constants say:
//! `fixpt-runtime/src/native-arm64.conv`, which both checkers compare a
//! program's `define-convention` with, is generated by
//! `fixpt_native::direct::native_convention`. `FIXPT_BLESS=1` rewrites it.

#[test]
fn the_declaration_is_generated_from_the_machine() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixpt-runtime/src/native-arm64.conv");
    let made = fixpt_native::direct::native_convention();
    if std::env::var_os("FIXPT_BLESS").is_some() {
        std::fs::write(path, &made).expect("written");
    }
    let file = std::fs::read_to_string(path).expect("readable");
    assert_eq!(file, made, "{path} is out of date: FIXPT_BLESS=1 cargo test -p fixpt-native --test convention");
}
